from pathlib import Path
import json,statistics as S,hashlib
P=Path(__file__).resolve().parent;R=P.parent.parent;d=json.loads((P/'results.json').read_text());assert d['status']=='COMPLETE'
engines=['SinglePoly','MultiPoly','NoPoly','value','gradient'];lines=['# Triple direct integration timing','',d['protocol'],'','One lens geometry, 12 source disks, 48 conditions. Linear LD coefficient u=0.5. Each cell below is the median across disks of each disk’s 16-call median; milliseconds. Ratios are computed per disk before aggregation. CPU frequency and unrelated system load are uncontrolled. VBM columns are value only.','', '| u | rtol | SinglePoly | MultiPoly | NoPoly | lcbinint value | lcbinint value+8 derivatives | median derivative overhead |','|---|---|---|---|---|---|---|---|']
agg=[]
for u in [0.,.5]:
 for tol in [1e-3,1e-4]:
  rows=[r for r in d['rows']if r['limb']==u and r['rtol']==tol]; med={k:S.median(r['summary'][k]['median_ms']for r in rows)for k in engines};over=S.median(100*(r['summary']['gradient']['median_ms']/r['summary']['value']['median_ms']-1)for r in rows)
  a=dict(limb=u,rtol=tol,median_ms=med,median_added_percent=over,value_wins_single=sum(r['summary']['value']['median_ms']<r['summary']['SinglePoly']['median_ms']for r in rows),gradient_wins_single=sum(r['summary']['gradient']['median_ms']<r['summary']['SinglePoly']['median_ms']for r in rows),value_speedup_single_median=S.median(r['summary']['SinglePoly']['median_ms']/r['summary']['value']['median_ms']for r in rows),gradient_speedup_single_median=S.median(r['summary']['SinglePoly']['median_ms']/r['summary']['gradient']['median_ms']for r in rows));agg.append(a)
  lines.append('|'+ '|'.join([str(u),str(tol),*[f'{med[k]:.3f}'for k in engines],f'{over:.1f}%'])+'|')
checks=dict(conditions=len(d['rows']),excluded=len(d['excluded']),methods=sorted(set(r['route']['method']for r in d['rows'])),native_nonconverged=[(i,k)for i,r in enumerate(d['rows'])for k in ['value','gradient']if not r['summary'][k]['converged']],gradient_invalid=[i for i,r in enumerate(d['rows'])if not r['summary']['gradient']['gradient_valid']],above_requested=[(i,k)for i,r in enumerate(d['rows'])for k,z in r['summary'].items()if max(z['relative_differences'].values())>r['rtol']],max_relative_difference=max(v for r in d['rows']for z in r['summary'].values()for v in z['relative_differences'].values()))
lines+=['','## Checks','',json.dumps(checks,indent=2),'','Every condition was freshly screened through the current normal finite-source router (method 2 = image-plane Cartesian integration). No point/hex cases were admitted. Direct integration, not light-curve API, is timed. Repeated-point warm performance includes retained support caches; first calls are retained separately in results.json.','', 'Accuracy comparison uses the saved independent SinglePoly/MultiPoly/NoPoly tight runs at rtol=1e-7 for the identical inputs. These references are diagnostics, not certified truth; the previous reference audit found inter-engine spread up to 9.12e-6. No new derivative finite-difference certification was performed for these 12 disks; gradient_valid indicates usable output, not certified precision. The existing separate gradient regression suite remains the accuracy evidence.','', '## Per-condition timing','','| x | y | rho | u | rtol | SinglePoly | MultiPoly | NoPoly | value | value+derivatives |','|---|---|---|---|---|---|---|---|---|---|']
for r in d['rows']:lines.append('|'+ '|'.join([*[str(x)for x in r['source']],str(r['rho']),str(r['limb']),str(r['rtol']),*[f"{r['summary'][k]['median_ms']:.3f}"for k in engines]])+'|')
(P/'REPORT.md').write_text('\n'.join(lines)+'\n');(P/'summary.json').write_text(json.dumps(dict(aggregate=agg,checks=checks),indent=2))
paths=[P/'run.py',P/'summarize.py',P/'router.so',P/'results.json',R/'evidence/triple_natural_integral_benchmark/results.json',R/'evidence/triple_hex_route_audit/router.cpp',R/'build-triple-native/liblcbinint_magnification.a',R/'build-triple-native/liblcbinint_lightcurve.a',R/'build-triple-native/liblcbinint_fused_gradient.a',*list((R/'src/lcbinint/magnification/algebraic_boundary/triple').glob('*.hpp'))]
(P/'hashes.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest()for p in paths},indent=2))
print(json.dumps(dict(aggregate=agg,checks=checks),indent=2))
